#!/bin/bash
# one before/after image per kit of the first batch (reference frames are for comparison only)
set -e
cd /home/noah/2k-worktrees/.b77-scratch/b81/uniforms
S="python3 tools/showcase.py"; R=work/fix/renders
L="LAC/2026-10-11_DEN_primary-home"; M="MIN/2026-10-04_MIA_primary-home"; B="BUF/2026-10-04_NE_primary-home"; BA="BUF/2026-10-12_LAR_primary-away"; G=$PWD/refs/gud_thumbs
$S showcase/LAC_home_before_after.png "Chargers home (24H0): jersey numbers upright" --ref "$L/jersey_back_0552.jpg:760:400:340:460" --ref "$L/jersey_front_0217.jpg:560:560:800:520" --before $R:before_24H0 --after $R:after_24H0 --views front,back,tq,tb --height 500 --note "Real 2026: the numbers are upright (9, 10); only the name plate letters lean. The game drew the numbers slanted. After: the same digit shapes stood upright with one even gold outline, on all eight Chargers kit packages (home, road, gold, gold-pants and navy sets; the alternates' digits were also of uneven height)." --note "The gold pants are the real Week 2 combination; the reference game (Week 5) wore powder blue pants. Still open: the name plate letters should lean."
$S showcase/LAC_road_before_after.png "Chargers road (24A0): jersey numbers upright" --ref "LAC/2026-10-04_SEA_primary-away/helmet_back_0328.jpg" --before $R:before_24A0 --after $R:after_24A0 --views front,back,tq,tb --height 500 --note "Same correction as the home kit, in the road colours (powder blue numbers, gold outline)."
$S showcase/MIN_home_before_after.png "Vikings home (15H0): pants stripe at its real width, white socks" --ref "$M/pants_0750.jpg:1080:0:480:1000" --ref "$G/2026_MIN_D2.png" --before $R:before_15H0 --after $R:after_15H0 --views front,left,legs,back --height 520 --note "Real 2026 (Weeks 3 and 4): white pants with a broad purple band and a thin gold line on its front edge; white socks. The small drawing is the uniform database's record of that game." --note "The game had a hairline stripe (9 texels) and purple socks (those belong to the Week 1 classic look)."
$S showcase/MIN_road_before_after.png "Vikings road (15A0): pants stripe at its real width" --ref "$G/2026_MIN_C2.png" --ref "$M/pants_0750.jpg:1080:0:480:1000" --before $R:before_15A0 --after $R:after_15A0 --views front,left,legs,back --height 520 --note "Real 2026 (Weeks 2 and 5): purple pants with a broad white band and a thin gold line on its front edge, the mirror of the home pants (right). The game had 2 texels of white beside 5 of gold." --note "The road frames in the library do not show the stripe closely, so the drawing and the home pants are the reference."
$S showcase/BUF_home_before_after.png "Bills home (03H0): sleeve stripes" --ref "$B/helmet_right_0432.jpg:380:480:420:400" --before $R:before_03H0 --after $R:after_03H0 --views tq,side,left,front --height 480 --note "Real 2026: two white bars, each edged red above and below, with a blue gap between them. The game had three white bars split by two red lines."
$S showcase/BUF_road_before_after.png "Bills road (03A0): sleeve stripes" --ref "$BA/helmet_left_2158.jpg:980:360:420:400" --before $R:before_03A0 --after $R:after_03A0 --views tq,side,left,front --height 480 --note "Real 2026: two royal bars, each edged red above and below, with a white gap between them. The game had one red bar between two royal bars."
$S showcase/LAR_road_before_after.png "Rams road (23A0): the sol band on the royal pants" --ref "LAR/2026-10-04_PHI_primary-away/pants_0417.jpg:1160:560:760:520" --ref "$G/2026_LAR_B.png" --before $R:before_23A0 --after $R:after_23A0 --views front,left,legs,back --height 520 --note "Real 2026 (Week 4): royal pants with a white band and a broad sol (yellow) band. The small drawing is the uniform database's record of that game. The game had a single thin white line."
